// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout)
	router.GET(options.BaseURL+"/auth/me", wrapper.Me)
	router.POST(options.BaseURL+"/auth/recovery", wrapper.SolicitarRecuperacion)
	router.POST(options.BaseURL+"/auth/recovery/verify", wrapper.VerificarRecuperacion)
	router.POST(options.BaseURL+"/auth/register", wrapper.Register)
	router.GET(options.BaseURL+"/centro", wrapper.ListarCentros)
	router.POST(options.BaseURL+"/centro", wrapper.CrearCentro)
	router.GET(options.BaseURL+"/centro/:centroId", wrapper.ObtenerCentro)
	router.GET(options.BaseURL+"/incidentes", wrapper.ListarIncidentes)
	router.POST(options.BaseURL+"/incidentes", wrapper.CrearIncidente)
	router.GET(options.BaseURL+"/incidentes/:incidenteId", wrapper.ObtenerIncidente)
	router.PUT(options.BaseURL+"/incidentes/:incidenteId", wrapper.ActualizarIncidente)
	router.POST(options.BaseURL+"/incidentes/:incidenteId/tags", wrapper.AgregarTags)
	router.GET(options.BaseURL+"/reportes", wrapper.ListarReportes)
	router.POST(options.BaseURL+"/reportes", wrapper.CrearReporte)
	router.GET(options.BaseURL+"/reportes/cercanos", wrapper.ListarReportesCercanos)
	router.GET(options.BaseURL+"/reportes/me", wrapper.ListarMisReportes)
	router.DELETE(options.BaseURL+"/reportes/:reporteId", wrapper.EliminarReporte)
	router.GET(options.BaseURL+"/reportes/:reporteId", wrapper.ObtenerReporte)
	router.PATCH(options.BaseURL+"/reportes/:reporteId/avistamientos", wrapper.AgregarAvistamiento)
	router.POST(options.BaseURL+"/reportes/:reporteId/comentarios", wrapper.CrearComentario)
	router.PATCH(options.BaseURL+"/reportes/:reporteId/estado", wrapper.CambiarEstadoReporte)
	router.POST(options.BaseURL+"/reportes/:reporteId/multimedia", wrapper.SubirMultimedia)
	router.PUT(options.BaseURL+"/reportes/:reporteId/tags", wrapper.ActualizarTagsReporte)
	router.GET(options.BaseURL+"/roles", wrapper.ListarRoles)
	router.GET(options.BaseURL+"/tipos-centro", wrapper.ListarTiposCentro)
	router.POST(options.BaseURL+"/tipos-centro", wrapper.CrearTipoCentro)
	router.GET(options.BaseURL+"/tipos-centro/:tipoCentroId", wrapper.ObtenerTipoCentro)
	router.GET(options.BaseURL+"/users", wrapper.ListarUsuarios)
}

